// Preview (D-31): an integrator trying their own agent from the dashboard. A preview turn is an
// ordinary data-plane turn run for a user whose id starts with "preview:". Everything that treats
// preview differently (passages in the stream, audit event names, owner-only error detail) keys off that id, which only the Worker assigns: end-user ids are "<https origin>|<id>"
// (D-29) and dashboard ids are generated by better-auth.
export const PREVIEW_PREFIX = "preview:";
export const previewUserId = (ownerId: string) => `${PREVIEW_PREFIX}${ownerId}`;
export const isPreviewUser = (userId: string) => userId.startsWith(PREVIEW_PREFIX);

// The coarse reason lives beside the other LLM helpers, so the dashboard's connection check words failures the same way.
export { llmErrorCode } from "../llm.js";
